-- =============================================================================
-- Replace the active project catalogue with the ISD Lab catalogue (Oct 2026, 40 projects).
-- GENERATED by supabase/import/project_catalogue_2026-10/generate.py - edit catalogue.py instead.
--
-- Requires migrations 0001-0009 and the applied COMPONENTS Audit (inventory items are
-- found through inventory_source_records, so the live inventory IDs are used and no
-- inventory item is created or changed).
--
--   1. Every active project that is not part of this catalogue is ARCHIVED (never deleted);
--      its previous status is saved in project_status_backup for rollback_catalogue.sql.
--      Requests and history that reference old projects are untouched.
--   2. The 40 projects are inserted as drafts, their components linked, then published.
--   3. Re-running while the catalogue is live only adds catalogue projects that are missing:
--      it archives nothing and leaves projects and requirements edited in the app alone.
--      After rollback_catalogue.sql it replaces the active catalogue again and gives every
--      catalogue project back the status it had before the rollback.
-- =============================================================================
begin;

select set_config('request.jwt.claim.sub',
  (select id::text from public.profiles where role = 'admin' and status = 'active' order by created_at limit 1), true);
select set_config('request.jwt.claims',
  json_build_object('sub', current_setting('request.jwt.claim.sub', true), 'role', 'authenticated')::text, true);

do $$
begin
  if (select count(*) from public.inventory_source_records
       where batch_key = 'components-audit-2026-10-12' and status = 'applied') = 0 then
    raise exception 'Apply the COMPONENTS Audit to the inventory first (no applied audit rows found).';
  end if;
end $$;

-- Replace the active catalogue only on the first load, or after rollback_catalogue.sql (which leaves
-- a 'project-catalogue-2026-10:rolled-back' row per catalogue project). Otherwise the catalogue is already live.
create temp table _catalogue_run on commit drop as
select not exists (select 1 from public.projects where catalogue_key like 'project-catalogue-2026-10:%')
       or exists (select 1 from public.project_status_backup where batch_key = 'project-catalogue-2026-10:rolled-back') as replace_active;
create temp table _catalogue_new (id uuid primary key) on commit drop;

-- 1. Archive the old active catalogue (reversible).
insert into public.project_status_backup (batch_key, project_id, previous_status)
select 'project-catalogue-2026-10', p.id, p.status from public.projects p
 where (select replace_active from _catalogue_run)
   and p.status <> 'archived' and (p.catalogue_key is null or p.catalogue_key not like 'project-catalogue-2026-10:%')
on conflict do nothing;
update public.projects set status = 'archived'
 where (select replace_active from _catalogue_run)
   and status <> 'archived' and (catalogue_key is null or catalogue_key not like 'project-catalogue-2026-10:%');

-- 2. Projects (remembering which ones this run inserted).
with v (catalogue_key, name, slug, category, difficulty, est_hours_min, est_hours_max, description, instructions,
        learning_outcomes, objectives, prerequisites, hardware_software, expected_outcome, testing_steps,
        safety_notes, extensions, external_requirements, verification_note, image_path, image_alt) as (
values
  ('project-catalogue-2026-10:01', 'Obstacle-Avoiding Robot', 'obstacle-avoiding-robot', 'Robotics', 'beginner', 4, 8, 'A four-wheel robot that measures distance with an ultrasonic sensor and steers away from obstacles on its own.', '1. Assemble the chassis
Mount the geared motors and wheels on the DIY 4W drive base; fix the Arduino and L298N with standoffs.

2. Wire the motor driver
Connect the left and right motor pairs to the L298N outputs and its IN1–IN4 pins to Arduino digital pins.

3. Mount the sensor
Fix the ultrasonic sensor in its holder at the front; wire TRIG/ECHO to two digital pins.

4. Program the behaviour
Read the distance every 50 ms; drive forward when clear, otherwise stop, reverse briefly and turn.

5. Tune
Adjust the stopping distance and turn time on the floor.', array['Measure distance with an HC-SR04 ultrasonic sensor', 'Drive DC motors through an L298N H-bridge', 'Write a simple sense-decide-act control loop']::text[], array['Measure distance with an HC-SR04 ultrasonic sensor', 'Drive DC motors through an L298N H-bridge', 'Write a simple sense-decide-act control loop']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Breadboard wiring and reading a module pin-out']::text[], array['Arduino Uno, ultrasonic sensor, L298N, DIY 4W drive chassis with geared motors, 2 × 18650 cells', 'Arduino IDE on a laptop', 'Jumper wires and screwdriver from the lab']::text[], 'The robot drives around a room and turns away before touching walls or boxes.', array['Print distances to the Serial Monitor and compare with a ruler at 10, 20 and 50 cm', 'Run each motor direction on its own with the wheels lifted', 'Place boxes in its path and confirm it stops before contact']::text[], array['Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.', 'Lift the wheels off the bench when testing motors.', 'Disconnect power before changing any wiring.']::text[], array['Add a servo to sweep the sensor and choose the clearer side', 'Use PWM speed control for smoother turns']::text[], '{}'::text[], null, '/projects/obstacle-avoiding-robot.svg', 'Four-wheel robot chassis with an Arduino, an L298N motor driver and an ultrasonic sensor at the front facing an obstacle'),
  ('project-catalogue-2026-10:02', 'Bluetooth-Controlled Robot', 'bluetooth-controlled-robot', 'Robotics', 'beginner', 4, 8, 'Drive a robot car from a phone: an HC-05 Bluetooth module receives commands and the Arduino turns them into motor movement.', '1. Assemble the drive base
Fit motors, wheels, Arduino and L298N on the DIY 4W drive chassis.

2. Connect the HC-05
HC-05 TX → Arduino RX (via SoftwareSerial pins); Arduino TX → HC-05 RX through a 1 kΩ/2 kΩ divider (3.3 V logic).

3. Define commands
F, B, L, R, S for forward, back, left, right, stop; parse them in loop().

4. Pair and drive
Pair the phone (default PIN 1234), connect from the app and test each command.', array['Use serial communication over Bluetooth (HC-05)', 'Map received characters to motor commands', 'Control motor direction and speed with an L298N']::text[], array['Use serial communication over Bluetooth (HC-05)', 'Map received characters to motor commands', 'Control motor direction and speed with an L298N']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Breadboard wiring and reading a module pin-out']::text[], array['Arduino Uno, HC-05, L298N, DIY 4W drive chassis, 2 × 18650 cells', 'Arduino IDE on a laptop', 'Android phone with a Bluetooth serial controller app (student’s own)']::text[], 'The robot responds to phone buttons within a fraction of a second and stops when commanded.', array['Send commands from a serial terminal app and watch the Serial Monitor echo', 'Check that every command moves the correct wheels', 'Confirm the robot stops if the app sends S']::text[], array['Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.', 'Never connect the HC-05 RX pin directly to 5 V logic – use the divider.', 'Test at low speed in an open area.']::text[], array['Add a fail-safe stop when no command arrives for one second', 'Add speed levels with PWM']::text[], '{}'::text[], null, '/projects/bluetooth-controlled-robot.svg', 'Robot car with an HC-05 Bluetooth module wirelessly linked to a smartphone controller'),
  ('project-catalogue-2026-10:03', 'Line-Following Robot', 'line-following-robot', 'Robotics', 'beginner', 4, 8, 'A two-wheel robot that follows a black line on the floor using two IR reflectance sensors.', '1. Build the base
Assemble the DIY 2W drive with its castor wheel and mount the electronics.

2. Fit the sensors
Mount two IR modules 1–2 cm above the floor, either side of the line; set each threshold with its potentiometer.

3. Wire and program
If the left sensor sees black, turn left; if the right sees black, turn right; otherwise go straight.

4. Make a track
Tape a closed loop with gentle curves on a light floor.', array['Read IR reflectance sensors', 'Implement differential steering', 'Tune a simple bang-bang or proportional controller']::text[], array['Read IR reflectance sensors', 'Implement differential steering', 'Tune a simple bang-bang or proportional controller']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Breadboard wiring and reading a module pin-out']::text[], array['Arduino Uno, 2 IR sensor modules, L298N, DIY 2W drive chassis, 2 × 18650 cells', 'Arduino IDE on a laptop']::text[], 'The robot completes laps of the taped track without losing the line.', array['Check each sensor’s LED switches over black tape and white floor', 'Run straight sections first, then curves', 'Time three laps and note any departures']::text[], array['Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.', 'Disconnect power before changing any wiring.']::text[], array['Use more IR sensors and a PID controller', 'Add junction detection for a maze']::text[], array['Black insulating tape for the track']::text[], null, '/projects/line-following-robot.svg', 'Two-wheel robot with IR sensors underneath following a black line track'),
  ('project-catalogue-2026-10:04', 'Servo-Based Robotic Arm', 'servo-robotic-arm', 'Robotics', 'intermediate', 8, 16, 'Program the lab’s 6-DoF mini arm joint by joint, then combine moves into a basic pick-and-place routine.', '1. Inspect the arm
Identify each joint’s servo and its safe angle range; check whether the arm has its own controller board.

2. Power safely
Power the servos from the separate supply, sharing ground with the Arduino.

3. Move one joint at a time
Write a sketch that moves each servo slowly between limits.

4. Record poses
Store joint angles for home, reach, grip and lift.

5. Sequence
Interpolate between poses to pick up a small foam block.', array['Control hobby servos with PWM', 'Understand joint angles and workspace limits', 'Sequence movements smoothly']::text[], array['Control hobby servos with PWM', 'Understand joint angles and workspace limits', 'Sequence movements smoothly']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Basic geometry (angles)']::text[], array['6 DoF Mini Arm (lab use), Arduino Uno, external 5–6 V supply for the servos', 'Arduino IDE on a laptop with the Servo library']::text[], 'The arm moves smoothly between stored poses and repeats a simple pick-and-place.', array['Verify each joint stays within its mechanical limits', 'Repeat the pick-and-place ten times and count successes']::text[], array['Keep hands clear of the arm while it moves.', 'Never power several servos from the Arduino 5 V pin.', 'This equipment is for use inside the lab only.']::text[], array['Control the arm from a joystick or potentiometers', 'Add inverse kinematics for target positions']::text[], '{}'::text[], 'Confirm whether the 6 DoF Mini Arm includes its own servo controller and the voltage its servos need.', '/projects/servo-robotic-arm.svg', 'Six-degree-of-freedom desktop robotic arm with servo joints lifting a small block'),
  ('project-catalogue-2026-10:05', 'Omnidirectional Robot', 'omnidirectional-robot', 'Robotics', 'advanced', 12, 24, 'Explore holonomic motion on the lab’s Smorphi mecanum platform: strafing, rotating in place and following paths.', '1. Read the platform guide
Learn how Smorphi is powered, charged and programmed, and its speed limits.

2. Basic motions
Command forward, sideways and rotate-in-place motions and observe the wheels.

3. Kinematics
Write a function that converts (vx, vy, ω) to the four wheel speeds.

4. Path following
Drive a square without changing heading, then a circle while facing the centre.', array['Understand mecanum wheel kinematics', 'Command forward, sideways and rotational velocities', 'Plan and follow simple paths']::text[], array['Understand mecanum wheel kinematics', 'Command forward, sideways and rotational velocities', 'Plan and follow simple paths']::text[], array['Programming experience in C++ or Python', 'Vectors and basic trigonometry']::text[], array['Smorphi with AI features (lab use)', 'Smorphi programming environment supplied with the platform', 'Laptop']::text[], 'The robot moves in any direction without turning first and follows a planned square path.', array['Measure drift after a 1 m sideways move', 'Repeat the square path three times and compare end positions']::text[], array['Run in a clear, enclosed area at low speed.', 'Follow the platform’s charging instructions.', 'This equipment is for use inside the lab only.']::text[], array['Add obstacle avoidance with the platform’s sensors', 'Compare with the Twin Bot drive system']::text[], '{}'::text[], null, '/projects/omnidirectional-robot.svg', 'Modular mecanum-wheel robot platform moving sideways with motion arrows'),
  ('project-catalogue-2026-10:06', '3D-Printed Robot Chassis', '3d-printed-robot-chassis', 'Robotics', 'intermediate', 8, 16, 'Design a custom robot chassis in CAD, print it on the lab’s 3D printer and build a working robot on it.', '1. Measure
Measure motors, boards and battery holder; plan mounting holes.

2. Design
Model a base plate with motor clamps, standoffs and a sensor mount.

3. Print
Slice with suitable infill and supports; print with staff supervision.

4. Assemble
Fit motors, wheels, electronics and wiring with screws from the screw box.

5. Test drive
Load a simple drive or obstacle-avoiding sketch.', array['Design printable parts in CAD', 'Prepare and slice a print', 'Integrate motors, driver and sensor on a custom frame']::text[], array['Design printable parts in CAD', 'Prepare and slice a print', 'Integrate motors, driver and sensor on a custom frame']::text[], array['Basic CAD (Fusion 360, Tinkercad or FreeCAD)', 'Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['3D printer (lab use), Arduino Uno, L298N, 2 small DC motors, ultrasonic sensor, 18650 cells', 'CAD software and a slicer (e.g. Cura)']::text[], 'A printed chassis that carries the electronics securely and drives without flexing.', array['Check every part fits before final assembly', 'Drive for five minutes and inspect for cracks or loose mounts']::text[], array['The printer nozzle and bed are hot – do not touch during or just after printing.', 'Only start prints with staff permission.', 'Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.']::text[], array['Add a battery compartment with a hinged lid', 'Design snap-fit mounts instead of screws']::text[], array['PLA filament', 'Wheels compatible with the DC motor shafts']::text[], null, '/projects/3d-printed-robot-chassis.svg', '3D printer printing a robot chassis plate next to motors and an Arduino'),
  ('project-catalogue-2026-10:07', 'IoT Smart Home Automation', 'iot-smart-home-automation', 'IoT & Embedded', 'intermediate', 8, 16, 'Control four low-voltage loads from a web page served by an ESP32, with a PIR sensor for automatic lighting.', '1. Wire the relay board
Connect IN1–IN4 to ESP32 GPIOs; power the relay side from 5 V with common ground.

2. Add loads
Use LEDs with resistors as the four “appliances”.

3. Build the web server
Serve a page with four toggle buttons that call /relay?ch=n&on=1.

4. Add automation
Turn channel 1 on for 30 s when the PIR detects motion.', array['Serve a web interface from an ESP32', 'Switch loads with an opto-isolated relay module', 'Combine manual and sensor-based control']::text[], array['Serve a web interface from an ESP32', 'Switch loads with an opto-isolated relay module', 'Combine manual and sensor-based control']::text[], array['Arduino IDE with ESP32 board support', 'Basic HTML', 'Breadboard wiring and reading a module pin-out']::text[], array['ESP32, 4-channel relay module, PIR sensor, LEDs as stand-in loads', 'Arduino IDE (ESP32 core), Wi-Fi network']::text[], 'A phone on the same Wi-Fi can switch four outputs, and the light turns on automatically when someone walks past.', array['Toggle each channel from the page and confirm the relay click and LED', 'Walk past the PIR and time the automatic light']::text[], array['Use only low-voltage (≤12 V) loads – do not connect mains to the relays.', 'Disconnect power before changing any wiring.']::text[], array['Add MQTT and a cloud dashboard', 'Schedule loads by time of day']::text[], '{}'::text[], null, '/projects/iot-smart-home-automation.svg', 'ESP32 board connected to a four-channel relay module controlling lights from a phone over Wi-Fi'),
  ('project-catalogue-2026-10:08', 'Smart Irrigation System', 'smart-irrigation-system', 'IoT & Embedded', 'beginner', 4, 8, 'Water a plant only when it needs it: a soil-moisture sensor decides when a relay switches a small pump on.', '1. Calibrate
Record sensor readings in dry soil and freshly watered soil.

2. Wire
Sensor to A0; relay IN to a digital pin; pump powered through the relay contacts.

3. Program
Pump on below the dry threshold, off above the wet threshold (hysteresis).

4. Install
Place the probe near the roots and route the tube to the pot.', array['Read an analogue soil-moisture sensor', 'Use thresholds with hysteresis', 'Switch a pump safely through a relay']::text[], array['Read an analogue soil-moisture sensor', 'Use thresholds with hysteresis', 'Switch a pump safely through a relay']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, soil moisture sensor, 1-channel relay', 'Small 5 V submersible pump with tubing (not stocked)', 'Arduino IDE on a laptop']::text[], 'The pump runs only when the soil is dry and stops once it is moist.', array['Test with a cup of dry and wet soil', 'Confirm the pump cannot run longer than a maximum time']::text[], array['Keep the electronics away from water; mount them above the pot.', 'Use a low-voltage pump only.']::text[], array['Log moisture to an SD card or the cloud', 'Add a rain sensor to skip watering']::text[], array['Small 5 V water pump and tubing']::text[], null, '/projects/smart-irrigation-system.svg', 'Potted plant with a soil moisture probe, an Arduino and a relay driving a small water pump'),
  ('project-catalogue-2026-10:09', 'Environmental Monitoring Station', 'environmental-monitoring-station', 'IoT & Embedded', 'beginner', 6, 12, 'Measure temperature and air quality with an ESP32 and show the readings on a web page.', '1. Wire sensors
Temperature sensor to an ADC pin; gas sensor AO to another ADC pin (scale to 3.3 V).

2. Warm up
Let the MQ sensor heat for several minutes before taking readings.

3. Convert
Turn temperature voltage into °C; record gas readings as relative values.

4. Serve
Show live values on a web page that refreshes every few seconds.', array['Read analogue sensors with the ESP32 ADC', 'Convert raw readings to units', 'Publish data over Wi-Fi']::text[], array['Read analogue sensors with the ESP32 ADC', 'Convert raw readings to units', 'Publish data over Wi-Fi']::text[], array['Arduino IDE with ESP32 board support', 'Breadboard wiring and reading a module pin-out']::text[], array['ESP32, analogue temperature sensor, MQ-series gas sensor', 'Arduino IDE (ESP32 core), Wi-Fi']::text[], 'A web page shows the room temperature and a relative air-quality reading that changes with conditions.', array['Compare temperature with a reference thermometer', 'Check the gas reading rises with hand-sanitiser vapour nearby']::text[], array['The MQ sensor heater gets hot – do not touch it.', 'Never test with flammable gases.']::text[], array['Add humidity sensing and charts', 'Push data to a cloud service']::text[], '{}'::text[], null, '/projects/environmental-monitoring-station.svg', 'ESP32 weather station with temperature and gas sensors sending readings to a dashboard'),
  ('project-catalogue-2026-10:10', 'RFID-Based Access Control', 'rfid-access-control', 'IoT & Embedded', 'intermediate', 6, 12, 'Grant or deny entry with RFID cards: authorised tags open a servo latch and the LCD shows who was admitted.', '1. Read tags
Wire the RFID reader (3.3 V) and print each tag’s UID.

2. Allow-list
Store approved UIDs; compare each scan.

3. Feedback
Green LED + “Access granted” or red LED + “Denied” on the LCD.

4. Latch
Rotate the servo to unlock for three seconds, then relock.', array['Read RFID tag UIDs over SPI', 'Store an allow-list', 'Drive a servo latch and LCD feedback']::text[], array['Read RFID tag UIDs over SPI', 'Store an allow-list', 'Drive a servo latch and LCD feedback']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Arrays and string comparison']::text[], array['Arduino Uno, RFID reader with tags, SG90 servo, 16×2 LCD with I2C adapter, LEDs', 'Arduino IDE on a laptop with MFRC522 and LiquidCrystal_I2C libraries']::text[], 'Authorised cards unlock the latch; unknown cards are refused and shown on screen.', array['Scan authorised and unauthorised tags ten times each', 'Confirm the latch always relocks']::text[], array['Power the RFID reader from 3.3 V, not 5 V.', 'Disconnect power before changing any wiring.']::text[], array['Log access with timestamps (add the RTC module)', 'Add an admin card that enrols new tags']::text[], '{}'::text[], null, '/projects/rfid-access-control.svg', 'RFID card reader next to a door latch with an LCD showing access granted'),
  ('project-catalogue-2026-10:11', 'GSM-Based Alert System', 'gsm-alert-system', 'IoT & Embedded', 'intermediate', 6, 12, 'Send an SMS when a motion sensor is triggered, using a SIM800L GSM module.', '1. Power
Set the buck converter to about 4.0 V and connect it to the SIM800L with a short, thick lead.

2. Talk to the modem
Use SoftwareSerial to send AT, AT+CSQ and AT+CREG? and read the replies.

3. Send an SMS
Use AT+CMGF=1 and AT+CMGS to send a test message.

4. Trigger
Send one alert when the PIR fires, then wait before the next.', array['Use AT commands to control a GSM modem', 'Power a GSM module correctly', 'Debounce and rate-limit alerts']::text[], array['Use AT commands to control a GSM modem', 'Power a GSM module correctly', 'Debounce and rate-limit alerts']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Serial communication']::text[], array['Arduino Uno, SIM800L, PIR sensor, DC buck supply set to about 4 V', 'Active SIM card with SMS (not stocked)', 'Arduino IDE on a laptop']::text[], 'A phone receives an SMS within seconds of motion being detected.', array['Check signal quality (AT+CSQ) before testing', 'Trigger the PIR and time SMS delivery', 'Confirm repeated motion does not flood messages']::text[], array['The SIM800L draws current spikes – use the buck supply, not the Arduino 5 V pin.', 'Use your own SIM and agree costs before testing.']::text[], array['Reply to SMS commands such as STATUS', 'Add a GPS location to alerts']::text[], array['Active SIM card with SMS credit']::text[], null, '/projects/gsm-alert-system.svg', 'SIM800L GSM module wired to an Arduino sending an SMS alert to a phone'),
  ('project-catalogue-2026-10:12', 'Fire and Flame Detection Alarm', 'fire-flame-detection-alarm', 'Sensors & Safety', 'beginner', 3, 6, 'Sound a buzzer and flash an LED when an IR flame sensor detects a flame.', '1. Wire
Flame sensor DO/AO to Arduino; buzzer and LEDs to outputs.

2. Calibrate
Adjust the module potentiometer so room light does not trigger it.

3. Program
On detection, sound the buzzer and flash the red LED until reset.', array['Read a digital/analogue flame sensor', 'Set a detection threshold', 'Produce audible and visual alarms']::text[], array['Read a digital/analogue flame sensor', 'Set a detection threshold', 'Produce audible and visual alarms']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, flame sensor module, piezo buzzer, LEDs', 'Arduino IDE on a laptop']::text[], 'The alarm sounds within a second when a small flame is held in front of the sensor.', array['Test with a lighter flame at 20, 50 and 100 cm under supervision', 'Check sunlight or lamps do not cause false alarms']::text[], array['Flame tests only with staff present, away from paper and with no flammable materials nearby.', 'This is a teaching model, not a certified fire alarm.']::text[], array['Add the GSM module to send an SMS alert', 'Add a smoke/gas sensor']::text[], '{}'::text[], null, '/projects/fire-flame-detection-alarm.svg', 'Flame sensor module detecting a candle flame with a buzzer and red warning LED'),
  ('project-catalogue-2026-10:13', 'Smart Walking Stick', 'smart-walking-stick', 'Sensors & Safety', 'intermediate', 6, 12, 'An assistive walking stick that warns of obstacles ahead with a buzzer and vibration.', '1. Mount
Fix the ultrasonic sensor near the bottom of the stick, angled slightly forward.

2. Wire
Nano, buzzer and vibration motor (through a transistor) in a small enclosure near the handle.

3. Program
Beep and vibrate faster as obstacles get closer than 1 m.

4. Package
Secure wires along the stick and make the battery easy to remove.', array['Measure distance in real time', 'Give graded feedback (faster beeps when closer)', 'Package electronics for a wearable/handheld device']::text[], array['Measure distance in real time', 'Give graded feedback (faster beeps when closer)', 'Package electronics for a wearable/handheld device']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Breadboard wiring and reading a module pin-out']::text[], array['Walking stick, Arduino Nano, ultrasonic sensor, buzzer, vibration motor, 18650 cells', 'Arduino IDE on a laptop']::text[], 'Walking towards a wall, the user feels and hears increasingly urgent warnings.', array['Measure warning distance against a tape measure', 'Walk a corridor with obstacles and note any missed objects']::text[], array['Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.', 'Prototype only – not a replacement for a certified mobility aid.']::text[], array['Add a second sensor for head-height obstacles', 'Add a fall-detection accelerometer']::text[], '{}'::text[], null, '/projects/smart-walking-stick.svg', 'Walking stick fitted with an ultrasonic sensor and a handle unit that buzzes near obstacles'),
  ('project-catalogue-2026-10:14', 'Fingerprint-Based Attendance System', 'fingerprint-attendance-system', 'Sensors & Safety', 'intermediate', 8, 16, 'Enrol fingerprints and mark attendance with a timestamp shown on an LCD.', '1. Enrol
Run the library’s enrol example to store a few test fingerprints.

2. Match
On a successful match, look up the student ID.

3. Timestamp
Read the RTC and show “ID 3 – 09:12 present” on the LCD.

4. Log
Print each record over serial (or to an SD card as an extension).', array['Enrol and match fingerprints with an optical sensor', 'Keep time with an RTC', 'Design a small user interface']::text[], array['Enrol and match fingerprints with an optical sensor', 'Keep time with an RTC', 'Design a small user interface']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Serial communication']::text[], array['Arduino Uno, fingerprint reader, 16×2 LCD with I2C adapter, DS3231 RTC', 'Arduino IDE on a laptop with Adafruit Fingerprint and RTClib libraries']::text[], 'Enrolled users are recognised and their attendance time is displayed and logged.', array['Test each enrolled finger five times and record false rejects', 'Try an unenrolled finger and confirm it is refused']::text[], array['Use only volunteers’ test prints and delete them afterwards – do not store real biometric data.', 'Disconnect power before changing any wiring.']::text[], array['Upload records to a spreadsheet over Wi-Fi', 'Add duplicate-scan protection']::text[], '{}'::text[], null, '/projects/fingerprint-attendance-system.svg', 'Optical fingerprint sensor with an LCD showing an attendance record'),
  ('project-catalogue-2026-10:15', 'Heart Rate Monitoring Prototype', 'heart-rate-monitoring-prototype', 'Sensors & Safety', 'intermediate', 6, 12, 'Display pulse readings from a finger-clip heart-rate sensor on an LCD, for learning about biosignals.', '1. Wire
Sensor signal to A0; LCD on I2C.

2. Visualise
Plot raw readings in the Serial Plotter while resting a fingertip on the sensor.

3. Detect beats
Find peaks above an adaptive threshold and time the gap between them.

4. Display
Show a smoothed BPM value on the LCD.', array['Sample an analogue pulse signal', 'Detect beats and compute beats per minute', 'Filter noisy signals']::text[], array['Sample an analogue pulse signal', 'Detect beats and compute beats per minute', 'Filter noisy signals']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Basic signal concepts (sampling, noise)']::text[], array['Arduino Uno, heart rate monitor module, 16×2 LCD with I2C adapter', 'Arduino IDE on a laptop and Serial Plotter']::text[], 'The LCD shows a stable pulse reading that is close to a manual count.', array['Compare with a 30-second manual pulse count', 'Check readings with the finger still and slightly moving']::text[], array['For education only – never use it for medical decisions.', 'Use only the low-voltage sensor; no electrodes on the chest.']::text[], array['Add the wireless logger (project 38)', 'Detect irregular intervals']::text[], '{}'::text[], null, '/projects/heart-rate-monitoring-prototype.svg', 'Finger on a pulse sensor with a heartbeat waveform and BPM reading on an LCD'),
  ('project-catalogue-2026-10:16', 'Water Turbidity Monitoring', 'water-turbidity-monitoring', 'Sensors & Safety', 'beginner', 4, 8, 'Measure how cloudy water samples are with a turbidity sensor and show a relative reading.', '1. Wire
Sensor analogue output to A0; LCD on I2C.

2. Calibrate
Record readings for clean water and for water with increasing amounts of clay or milk.

3. Map
Convert readings into a relative 0–100 cloudiness scale.

4. Display
Show the value and a Clear/Cloudy/Dirty label.', array['Read an optical turbidity sensor', 'Calibrate against reference samples', 'Present relative measurements honestly']::text[], array['Read an optical turbidity sensor', 'Calibrate against reference samples', 'Present relative measurements honestly']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, turbidity sensor, 16×2 LCD with I2C adapter', 'Clear containers and water samples (not stocked)', 'Arduino IDE on a laptop']::text[], 'Different samples give clearly different, repeatable readings.', array['Measure each sample three times and compare spread', 'Check the sensor head is dried between samples']::text[], array['Keep the electronics dry; only the probe tip goes in water.', 'Do not drink test samples.']::text[], array['Log readings over time for a water tank', 'Combine with a temperature sensor']::text[], array['Clear containers and water samples']::text[], null, '/projects/water-turbidity-monitoring.svg', 'Turbidity probe dipped in a beaker of cloudy water with readings on a display'),
  ('project-catalogue-2026-10:17', 'AI Object Detection', 'ai-object-detection', 'AI & Advanced Systems', 'advanced', 12, 24, 'Run a pretrained object-detection model on the Jetson Nano with the Intel depth camera and draw labelled boxes in real time.', '1. Prepare
Check the Jetson’s power supply and SD-card image with staff.

2. Camera
Connect the Intel camera and confirm it streams.

3. Model
Run a pretrained SSD/YOLO model and display boxes and labels.

4. Evaluate
Measure frames per second and test on lab objects.', array['Set up an edge-AI board', 'Run a pretrained detection network', 'Measure inference speed and accuracy']::text[], array['Set up an edge-AI board', 'Run a pretrained detection network', 'Measure inference speed and accuracy']::text[], array['Python and Linux command line', 'Basic machine-learning concepts']::text[], array['Jetson Nano (lab use), Intel depth camera, monitor/keyboard', 'JetPack OS image, jetson-inference or similar, Python, librealsense']::text[], 'The screen shows live video with correctly labelled boxes around common objects.', array['Record FPS at two input resolutions', 'Count correct/incorrect detections on 20 test objects']::text[], array['The Jetson heatsink gets hot – keep the fan clear.', 'Lab use only; shut down properly before unplugging.']::text[], array['Use depth to report each object’s distance', 'Train on a custom dataset of lab components']::text[], array['Monitor, keyboard and mouse', 'microSD card with JetPack']::text[], 'Confirm the Jetson Nano power supply and OS image, and that this Intel depth camera model works with librealsense on the Jetson.', '/projects/ai-object-detection.svg', 'Jetson Nano board with a camera showing object-detection boxes on a screen'),
  ('project-catalogue-2026-10:18', 'Stereo Vision and Depth Mapping', 'stereo-vision-depth-mapping', 'AI & Advanced Systems', 'advanced', 12, 24, 'Use the ZED-2 stereo camera kit to compute depth maps and 3D point clouds of the lab.', '1. Start
Boot the Xavier NX kit and launch the ZED Explorer to confirm the camera works.

2. Depth
Capture a depth map and display it as a colour image.

3. Measure
Read the distance at chosen pixels and compare with a tape measure.

4. Point cloud
Export and view a point cloud of a scene.', array['Understand stereo disparity and depth', 'Use a vendor SDK to capture depth', 'Visualise and measure 3D scenes']::text[], array['Understand stereo disparity and depth', 'Use a vendor SDK to capture depth', 'Visualise and measure 3D scenes']::text[], array['Python or C++', 'Basic linear algebra']::text[], array['ZED-2 Stereolabs Xavier NX kit (lab use)', 'ZED SDK, Python API, monitor']::text[], 'Depth maps and a 3D point cloud of the lab, with measured distances within a few centimetres.', array['Compare measured distances at 0.5, 1 and 2 m', 'Check accuracy on shiny and dark surfaces']::text[], array['Lab use only; handle the camera by its body, not the lenses.', 'Shut the kit down properly before disconnecting power.']::text[], array['Detect people and report their 3D positions', 'Build a simple 3D reconstruction']::text[], '{}'::text[], null, '/projects/stereo-vision-depth-mapping.svg', 'ZED-2 stereo camera with a colourful depth map of a room'),
  ('project-catalogue-2026-10:19', 'LiDAR-Based Mapping and Navigation', 'lidar-mapping-navigation', 'AI & Advanced Systems', 'advanced', 16, 30, 'Build a 2D map of a room with the lab’s LiDAR and a ROS SLAM package, then plan paths on it.', '1. Identify
Find the LiDAR model and install its ROS driver on the mini PC.

2. Scan
Visualise live scans in RViz.

3. Map
Carry or slowly move the sensor around a room while SLAM builds the map.

4. Plan
Save the map and plan a path between two points.', array['Read 2D laser scans', 'Run a SLAM algorithm to build a map', 'Understand occupancy grids and path planning']::text[], array['Read 2D laser scans', 'Run a SLAM algorithm to build a map', 'Understand occupancy grids and path planning']::text[], array['Linux and ROS basics', 'Python or C++']::text[], array['2D LiDAR sensor and mini PC (lab use)', 'ROS with the LiDAR’s driver, SLAM toolbox/gmapping, RViz']::text[], 'A saved occupancy-grid map that matches the room layout.', array['Compare map dimensions with measured room size', 'Rebuild the map twice and compare']::text[], array['Most 2D LiDARs are Class 1 lasers, but never look into the emitter.', 'Lab use only.']::text[], array['Mount on the Twin Bot for autonomous navigation (project 40)', 'Detect moving people in scans']::text[], '{}'::text[], 'Confirm the LiDAR model, its connection (USB/serial) and an available ROS driver.', '/projects/lidar-mapping-navigation.svg', 'Spinning 2D LiDAR sensor with laser scan lines building a floor-plan map'),
  ('project-catalogue-2026-10:20', 'Drone Telemetry and Control', 'drone-telemetry-control', 'AI & Advanced Systems', 'advanced', 16, 30, 'Explore the C-DAC drone kit’s flight controller: read telemetry, configure it and understand control loops – flight only after staff approval.', '1. Inventory the kit
With staff, list what the kit contains and read its manuals.

2. Bench setup
With propellers removed, connect the flight controller to the ground-control software.

3. Telemetry
Record attitude and battery readings while tilting the frame by hand.

4. Review
Study the PID settings; any flight test only in an approved area with staff present.', array['Read telemetry (attitude, battery, GPS) from a flight controller', 'Understand PID attitude control', 'Follow drone safety procedures']::text[], array['Read telemetry (attitude, battery, GPS) from a flight controller', 'Understand PID attitude control', 'Follow drone safety procedures']::text[], array['Electronics and programming experience', 'Completion of the lab’s drone safety briefing']::text[], array['C-DAC drone kit with its supplied controller and software (lab use)', 'Ground-control software supplied with the kit']::text[], 'Live telemetry from the flight controller and a written understanding of its control settings.', array['Tilt the frame and confirm the attitude display follows', 'Check battery voltage readings against a meter']::text[], array['Propellers OFF for all bench work.', 'No flying without staff approval, an approved area and applicable permissions.', 'Handle LiPo batteries per the kit instructions.']::text[], array['Log telemetry and plot it after a supervised flight', 'Study failsafe settings']::text[], '{}'::text[], 'Verify the kit contents, its software and the safety and permission requirements before any flight.', '/projects/drone-telemetry-control.svg', 'Quadcopter drone kit with telemetry data shown on a ground-control screen'),
  ('project-catalogue-2026-10:21', 'Smart Parking Assistant', 'smart-parking-assistant', 'Sensors & Automation', 'beginner', 4, 8, 'Help a driver park: an ultrasonic sensor lights green, yellow and red LEDs and beeps as a car gets closer.', '1. Wire
Ultrasonic sensor, three LEDs with resistors and a buzzer.

2. Bands
Green above 50 cm, yellow 20–50 cm, red and fast beeping below 20 cm.

3. Smooth
Average several readings to avoid flicker.', array['Measure distance continuously', 'Map distance bands to indicators', 'Design clear user feedback']::text[], array['Measure distance continuously', 'Map distance bands to indicators', 'Design clear user feedback']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, ultrasonic sensor, LEDs, buzzer', 'Arduino IDE on a laptop']::text[], 'A toy car approaching the sensor changes the lights and beeps at the right distances.', array['Check each band with a ruler', 'Move an object slowly and confirm no flicker between bands']::text[], array['Disconnect power before changing any wiring.']::text[], array['Show the distance on an LCD', 'Count free parking slots with several sensors']::text[], '{}'::text[], null, '/projects/smart-parking-assistant.svg', 'Car approaching a wall-mounted ultrasonic sensor with green, yellow and red distance lights'),
  ('project-catalogue-2026-10:22', 'Automatic Door Prototype', 'automatic-door-prototype', 'Sensors & Automation', 'intermediate', 6, 12, 'A model door that opens with a servo when a PIR sensor detects someone approaching, and closes after a delay.', '1. Build the model
Make a small door on a hinge with the servo horn attached.

2. Wire
PIR output to a digital pin; servo signal to a PWM pin.

3. Program
States: closed → opening → open (5 s) → closing; restart the timer if motion continues.', array['Use a PIR motion sensor', 'Control a servo smoothly', 'Design timed state machines']::text[], array['Use a PIR motion sensor', 'Control a servo smoothly', 'Design timed state machines']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, PIR sensor, SG90 servo', 'Cardboard or foam-board door model (not stocked)', 'Arduino IDE on a laptop']::text[], 'The model door opens when a hand approaches and closes a few seconds after it leaves.', array['Approach from different angles and distances', 'Check the door never closes while motion continues']::text[], array['Keep fingers clear of the hinge while the servo moves.', 'Disconnect power before changing any wiring.']::text[], array['Add RFID so only authorised cards open it', 'Count people entering']::text[], array['Cardboard or foam-board door model']::text[], null, '/projects/automatic-door-prototype.svg', 'Model sliding door with a motion sensor above it and a servo opening it'),
  ('project-catalogue-2026-10:23', 'Gas Leakage Alert', 'gas-leakage-alert', 'Sensors & Automation', 'beginner', 4, 8, 'Raise an alarm when an MQ-series gas sensor reading crosses a set threshold.', '1. Wire
Sensor AO to A0; buzzer and LEDs to outputs.

2. Warm up
Run the sensor for several minutes and note the clean-air reading.

3. Threshold
Set an alarm level well above clean air.

4. Alarm
Red LED and buzzer until the reading falls back, then green.', array['Use a heated MQ gas sensor', 'Set and test thresholds', 'Build a latching alarm']::text[], array['Use a heated MQ gas sensor', 'Set and test thresholds', 'Build a latching alarm']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, MQ-series gas sensor, buzzer, LEDs', 'Arduino IDE on a laptop']::text[], 'Exposing the sensor to a little sanitiser vapour triggers the alarm, which clears in clean air.', array['Log clean-air readings for five minutes', 'Test with sanitiser vapour (never fuel gas)']::text[], array['Never release LPG, butane or other flammable gas to test.', 'The sensor heater is hot.', 'Teaching model only – not a certified gas detector.']::text[], array['Send an SMS with the GSM module', 'Switch an exhaust fan with a relay']::text[], '{}'::text[], null, '/projects/gas-leakage-alert.svg', 'MQ gas sensor module with a warning buzzer and red alert LED'),
  ('project-catalogue-2026-10:24', 'Temperature-Controlled Fan', 'temperature-controlled-fan', 'Sensors & Automation', 'intermediate', 4, 8, 'Run a small DC fan faster as the temperature rises, using PWM through a MOSFET module.', '1. Wire the sensor
Temperature sensor output to A0; convert to °C.

2. Wire the motor
Motor powered from the cells through the MOSFET module; flyback diode across the motor.

3. Control
Off below 28 °C, then increase PWM duty with temperature up to full speed at 35 °C.', array['Read an analogue temperature sensor', 'Drive a motor with PWM and a MOSFET', 'Map temperature to speed']::text[], array['Read an analogue temperature sensor', 'Drive a motor with PWM and a MOSFET', 'Map temperature to speed']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Breadboard wiring and reading a module pin-out']::text[], array['Arduino Uno, temperature sensor, IRF520 MOSFET module, small DC motor, 1N4007 diode, 18650 cells', 'Small propeller/fan blade for the motor (not stocked)', 'Arduino IDE on a laptop']::text[], 'The fan speeds up when the sensor is warmed by hand and slows as it cools.', array['Warm the sensor and log temperature vs PWM duty', 'Confirm the motor stops below the lower threshold']::text[], array['Always fit the flyback diode across the motor.', 'Insert 18650 cells with the correct polarity, never short them, and charge them only with the lab charger.', 'Keep fingers away from the spinning blade.']::text[], array['Show temperature and speed on an LCD', 'Use the thermistor module and compare sensors']::text[], array['Small propeller or fan blade for the motor shaft']::text[], null, '/projects/temperature-controlled-fan.svg', 'Small DC fan driven by a MOSFET module with a temperature sensor and speed graph'),
  ('project-catalogue-2026-10:25', 'Light-Activated Lighting', 'light-activated-lighting', 'Sensors & Automation', 'beginner', 2, 4, 'Turn LEDs on automatically when it gets dark, using an LDR light sensor.', '1. Wire
LDR module output to A0 (or DO); three LEDs with resistors.

2. Measure
Print readings in bright light and when covered.

3. Control
LEDs on below the dark threshold, off above the light threshold.', array['Read a light-dependent resistor module', 'Use thresholds with hysteresis', 'Control several outputs']::text[], array['Read a light-dependent resistor module', 'Use thresholds with hysteresis', 'Control several outputs']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, LDR module, LEDs', 'Arduino IDE on a laptop']::text[], 'Covering the sensor turns the lights on; uncovering it turns them off without flicker.', array['Test at dusk-like light levels', 'Confirm no flicker near the threshold']::text[], array['Disconnect power before changing any wiring.']::text[], array['Dim the LEDs gradually with PWM', 'Combine with a PIR so lights only turn on when someone is present']::text[], '{}'::text[], null, '/projects/light-activated-lighting.svg', 'LDR light sensor switching on LED lamps as day turns to night'),
  ('project-catalogue-2026-10:26', 'Vibration Monitoring', 'vibration-monitoring', 'Sensors & Automation', 'beginner', 3, 6, 'Detect and measure vibration with an MPU-6050 accelerometer, using a vibration motor as a test source.', '1. Wire
MPU-6050 on I2C (SDA/SCL); vibration motor driven through a transistor.

2. Read
Plot X/Y/Z acceleration in the Serial Plotter.

3. Detect
Compute the change in acceleration magnitude and flag events above a threshold.

4. Test
Switch the vibration motor on and off next to the sensor.', array['Read an I2C accelerometer', 'Compute vibration magnitude', 'Detect events above a threshold']::text[], array['Read an I2C accelerometer', 'Compute vibration magnitude', 'Detect events above a threshold']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'I2C basics']::text[], array['Arduino Uno, MPU-6050, vibration motor', 'Arduino IDE on a laptop and Serial Plotter']::text[], 'The plot shows clear spikes when the motor vibrates and the program reports each event.', array['Compare readings with the motor on and off', 'Tap the bench and check detection sensitivity']::text[], array['Disconnect power before changing any wiring.']::text[], array['Compute vibration frequency with an FFT', 'Log events to an SD card']::text[], '{}'::text[], 'The audit lists no dedicated vibration sensor; confirm the MPU-6050 module works for this before publishing as buildable.', '/projects/vibration-monitoring.svg', 'MPU-6050 accelerometer on a vibrating surface with a waveform of vibration spikes'),
  ('project-catalogue-2026-10:27', 'GPS Tracking Prototype', 'gps-tracking-prototype', 'Sensors & Automation', 'intermediate', 6, 12, 'Read latitude, longitude and time from a NEO-6M GPS module and show them on an LCD.', '1. Wire
GPS TX to a SoftwareSerial RX pin; LCD on I2C.

2. Raw data
Print NMEA sentences to the Serial Monitor.

3. Parse
Use TinyGPS++ to extract position, satellites and time.

4. Display
Show coordinates on the LCD; test outdoors or by a window.', array['Parse NMEA sentences', 'Use a GPS library', 'Understand satellite fix and accuracy']::text[], array['Parse NMEA sentences', 'Use a GPS library', 'Understand satellite fix and accuracy']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Serial communication']::text[], array['Arduino Uno, NEO-6M GPS with antenna, 16×2 LCD with I2C adapter', 'Arduino IDE on a laptop with TinyGPS++']::text[], 'The LCD shows the current coordinates once the module has a satellite fix.', array['Note time to first fix outdoors', 'Compare coordinates with a phone map']::text[], array['Test outdoors only in safe, permitted areas.', 'Disconnect power before changing any wiring.']::text[], array['Send location by SMS with the GSM module', 'Log a route and plot it on a map']::text[], '{}'::text[], null, '/projects/gps-tracking-prototype.svg', 'NEO-6M GPS module receiving satellite signals with a location pin on a map'),
  ('project-catalogue-2026-10:28', 'Digital Notice or Status Display', 'digital-notice-display', 'Sensors & Automation', 'beginner', 3, 6, 'A 16×2 LCD notice board that scrolls messages and pages through them with pushbuttons.', '1. Wire
LCD through the I2C adapter; two pushbuttons to digital pins.

2. Messages
Store several notices in an array.

3. Scroll
Scroll long messages across the top line.

4. Navigate
Next/previous buttons change the message.', array['Drive a character LCD over I2C', 'Scroll text', 'Handle button input with debouncing']::text[], array['Drive a character LCD over I2C', 'Scroll text', 'Handle button input with debouncing']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, 16×2 LCD, I2C adapter, pushbuttons', 'Arduino IDE on a laptop with LiquidCrystal_I2C']::text[], 'The display scrolls readable notices and buttons switch between them.', array['Check every message displays fully', 'Press buttons rapidly and confirm one change per press']::text[], array['Disconnect power before changing any wiring.']::text[], array['Update messages over Bluetooth', 'Show lab equipment status']::text[], '{}'::text[], null, '/projects/digital-notice-display.svg', '16×2 LCD notice board showing a scrolling lab message'),
  ('project-catalogue-2026-10:29', 'Electronic Dice', 'electronic-dice', 'Sensors & Automation', 'beginner', 2, 4, 'Press a button to roll: seven LEDs show a random dice face.', '1. Layout
Arrange seven LEDs in the dice pattern on the breadboard.

2. Wire
Each LED through a resistor to a digital pin; pushbutton with internal pull-up.

3. Program
On press, animate briefly, then show a random face from 1 to 6.', array['Generate random numbers', 'Drive LED patterns', 'Debounce a pushbutton']::text[], array['Generate random numbers', 'Drive LED patterns', 'Debounce a pushbutton']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, 7 LEDs, resistors, pushbutton', 'Arduino IDE on a laptop']::text[], 'Each press shows a random dice face with all six faces appearing over many rolls.', array['Roll 120 times and count each face', 'Check every LED works']::text[], array['Disconnect power before changing any wiring.']::text[], array['Two dice with a total', 'Show the result on the LCD']::text[], '{}'::text[], null, '/projects/electronic-dice.svg', 'Seven LEDs on a breadboard arranged as a dice face showing five, with a pushbutton'),
  ('project-catalogue-2026-10:30', 'Touch-Controlled Switch', 'touch-controlled-switch', 'Sensors & Automation', 'beginner', 2, 4, 'Toggle a light with a capacitive touch sensor.', '1. Wire
Touch sensor output to a digital pin; LED with resistor.

2. Toggle
Change the LED state on each new touch (rising edge).

3. Refine
Ignore touches within 200 ms of the last one.', array['Read a touch sensor module', 'Implement a toggle (edge detection)', 'Avoid repeated triggers']::text[], array['Read a touch sensor module', 'Implement a toggle (edge detection)', 'Avoid repeated triggers']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, touch sensor module, LED', 'Arduino IDE on a laptop']::text[], 'Each tap turns the LED on or off reliably.', array['Tap 20 times and confirm 20 toggles', 'Hold a finger on the pad and confirm only one toggle']::text[], array['Disconnect power before changing any wiring.']::text[], array['Long-press to dim', 'Switch a low-voltage load through a relay']::text[], '{}'::text[], null, '/projects/touch-controlled-switch.svg', 'Finger tapping a capacitive touch sensor pad that switches on a light'),
  ('project-catalogue-2026-10:31', 'Smart Dustbin Prototype', 'smart-dustbin-prototype', 'Sensors & Automation', 'intermediate', 6, 12, 'A bin whose lid opens with a servo when a hand comes near the ultrasonic sensor.', '1. Mechanism
Attach the servo so its horn lifts the lid.

2. Sensor
Mount the ultrasonic sensor on the front of the bin.

3. Program
Open when something is closer than 20 cm; close after 3 s with no detection.', array['Detect proximity', 'Actuate a mechanism with a servo', 'Build a reliable mechanical linkage']::text[], array['Detect proximity', 'Actuate a mechanism with a servo', 'Build a reliable mechanical linkage']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, ultrasonic sensor, SG90 servo', 'Small bin with a hinged lid (not stocked)', 'Arduino IDE on a laptop']::text[], 'The lid opens as a hand approaches and closes by itself.', array['Approach 20 times and count successful openings', 'Check the lid closes fully every time']::text[], array['Keep fingers clear of the lid hinge.', 'Disconnect power before changing any wiring.']::text[], array['Add a fill-level sensor inside', 'Report when the bin is full']::text[], array['Small bin with a hinged lid']::text[], null, '/projects/smart-dustbin-prototype.svg', 'Dustbin with an ultrasonic sensor and a servo lifting the lid as a hand approaches'),
  ('project-catalogue-2026-10:32', 'Water-Level Indicator', 'water-level-indicator', 'Sensors & Automation', 'beginner', 3, 6, 'Show water levels in a container with LEDs and sound a buzzer when it is about to overflow.', '1. Probe
Place the sensing board (or probe wires) at the levels to detect.

2. Wire
Probe output to Arduino; LEDs for each level; buzzer.

3. Program
Light LEDs as levels are reached; buzz at the top level.', array['Sense water with conductive probes', 'Show levels with LEDs', 'Add an overflow alarm']::text[], array['Sense water with conductive probes', 'Show levels with LEDs', 'Add an overflow alarm']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['Arduino Uno, rain-sensor board used as a wet/dry probe, LEDs, buzzer', 'Container for water (not stocked)', 'Arduino IDE on a laptop']::text[], 'LEDs climb as the container fills and the buzzer sounds near the top.', array['Fill slowly and record when each level triggers', 'Empty and confirm the LEDs turn off']::text[], array['Keep the Arduino and wiring dry and above the container.', 'Disconnect power before changing any wiring.']::text[], array['Switch a pump off automatically', 'Send the level over Wi-Fi']::text[], array['Container for water']::text[], 'No dedicated water-level sensor is listed in the audit; confirm a suitable multi-level probe before marking this buildable.', '/projects/water-level-indicator.svg', 'Water tank with level probes and a column of LEDs showing the fill level'),
  ('project-catalogue-2026-10:33', 'Wireless Sensor Dashboard', 'wireless-sensor-dashboard', 'Sensors & Automation', 'intermediate', 8, 16, 'Stream temperature, sound and light readings from an ESP32 to a live web dashboard with charts.', '1. Wire
Three sensors to ESP32 ADC pins (3.3 V).

2. API
Serve /data returning JSON with the latest readings.

3. Dashboard
Serve a page that polls /data and updates three charts.

4. Polish
Show units, last-update time and connection status.', array['Serve JSON data from an ESP32', 'Build a small web dashboard', 'Handle several sensors on one board']::text[], array['Serve JSON data from an ESP32', 'Build a small web dashboard', 'Handle several sensors on one board']::text[], array['Arduino IDE with ESP32 board support', 'Basic HTML/JavaScript']::text[], array['ESP32, temperature sensor, sound sensor, LDR module', 'Arduino IDE (ESP32 core), Wi-Fi, browser']::text[], 'A browser on the same network shows three live charts that react to warmth, noise and light.', array['Change each condition and watch its chart respond', 'Disconnect Wi-Fi and confirm the page shows “offline”']::text[], array['Disconnect power before changing any wiring.']::text[], array['Store history in a database', 'Add alerts when values cross limits']::text[], '{}'::text[], null, '/projects/wireless-sensor-dashboard.svg', 'ESP32 with sensors streaming live charts to a laptop dashboard over Wi-Fi'),
  ('project-catalogue-2026-10:34', 'Robot Teleoperation Dashboard', 'robot-teleoperation-dashboard', 'Sensors & Automation', 'advanced', 12, 24, 'Drive the lab’s Twin Bot remotely from a web dashboard with live status.', '1. Investigate
With staff, find how the Twin Bot can be commanded (Wi-Fi, Bluetooth or serial).

2. Bridge
Write a small server that forwards commands to the robot.

3. Dashboard
Add arrow controls, speed slider and an emergency stop.

4. Safety
Stop the robot if no command arrives within one second.', array['Design a control interface', 'Send commands over a network link', 'Add safety stops']::text[], array['Design a control interface', 'Send commands over a network link', 'Add safety stops']::text[], array['Programming experience (Python or JavaScript)', 'Networking basics']::text[], array['Twin Bot (lab use), laptop', 'Platform SDK/firmware supplied with the robot, web framework of choice']::text[], 'The robot can be driven from the dashboard and always stops when the connection drops.', array['Measure command latency', 'Disconnect the laptop and confirm the robot stops']::text[], array['Operate in a clear area with someone watching the robot.', 'Lab use only.']::text[], array['Stream a camera view', 'Add waypoint driving']::text[], '{}'::text[], 'Confirm how the Twin Bot can be controlled remotely (its controller and network interface).', '/projects/robot-teleoperation-dashboard.svg', 'Laptop teleoperation dashboard with arrow controls driving a robot over Wi-Fi'),
  ('project-catalogue-2026-10:35', 'Robotic Pick-and-Place', 'robotic-pick-and-place', 'Interdisciplinary', 'advanced', 12, 24, 'Program the 6-DoF arm to move objects between marked locations reliably.', '1. Define positions
Mark pick and place spots and record joint angles for each.

2. Trajectory
Move through safe approach poses above each spot.

3. Grip
Close the gripper gently and check the object is held.

4. Repeat
Run a sequence that moves three objects.', array['Plan joint trajectories', 'Sequence grasp and release', 'Measure repeatability']::text[], array['Plan joint trajectories', 'Sequence grasp and release', 'Measure repeatability']::text[], array['Completion of the Servo-Based Robotic Arm project or equivalent', 'Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)']::text[], array['6 DoF Mini Arm (lab use), Arduino Uno, servo power supply', 'Arduino IDE on a laptop']::text[], 'The arm moves three objects to their targets in sequence without dropping them.', array['Run the sequence ten times and record placement error', 'Try objects of different sizes']::text[], array['Keep hands outside the arm’s reach while it runs.', 'Lab use only.']::text[], array['Detect object positions with a camera', 'Sort objects by colour']::text[], array['Small test objects (foam blocks)']::text[], 'Confirm whether the 6 DoF Mini Arm includes its own servo controller and the voltage its servos need.', '/projects/robotic-pick-and-place.svg', 'Robotic arm picking a block from one marked spot and placing it on another'),
  ('project-catalogue-2026-10:36', '3D-Printed Assistive Device', '3d-printed-assistive-device', 'Interdisciplinary', 'intermediate', 8, 20, 'Design and print a simple assistive aid, such as an easy-grip utensil handle or a key turner.', '1. Define the need
Choose a task and list the user’s requirements.

2. Design
Model the device with comfortable, rounded grips.

3. Prototype
Print a quick low-infill version and test the fit.

4. Refine
Improve the design and print the final version.', array['Apply user-centred design', 'Iterate a CAD design from feedback', 'Prepare reliable prints']::text[], array['Apply user-centred design', 'Iterate a CAD design from feedback', 'Prepare reliable prints']::text[], array['Basic CAD', 'Interest in assistive technology']::text[], array['3D printer (lab use), screws from the screw box', 'CAD software and a slicer']::text[], 'A printed device that makes the chosen task easier, with documented design changes.', array['Ask three testers to use it and record feedback', 'Check strength by applying normal working force']::text[], array['Printer parts are hot – do not touch during printing.', 'Only print with staff permission.', 'Remove sharp edges before testing.']::text[], array['Use flexible TPU for soft grips', 'Publish the design files openly']::text[], array['PLA or TPU filament']::text[], null, '/projects/3d-printed-assistive-device.svg', '3D printer with an ergonomic printed grip aid'),
  ('project-catalogue-2026-10:37', 'Real-Time Clock Display', 'real-time-clock-display', 'Interdisciplinary', 'beginner', 3, 6, 'Show the time and date from a DS3231 real-time clock module on a 16×2 LCD.', '1. Wire
RTC and LCD share the I2C bus.

2. Set time
Set the clock once from the computer’s time.

3. Display
Show HH:MM:SS on line 1 and the date on line 2.

4. Check
Unplug for a minute and confirm the time is kept.', array['Use an I2C RTC module', 'Set and keep time across power cycles', 'Format time and date']::text[], array['Use an I2C RTC module', 'Set and keep time across power cycles', 'Format time and date']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'I2C basics']::text[], array['Arduino Uno, DS3231 RTC module (listed as “DC 3231”), 16×2 LCD with I2C adapter', 'Arduino IDE on a laptop with RTClib']::text[], 'A clock that keeps correct time even after power is removed.', array['Compare with a phone clock after 24 hours', 'Power-cycle and confirm the time is retained']::text[], array['Fit the RTC’s coin cell with the correct polarity.', 'Disconnect power before changing any wiring.']::text[], array['Add alarms with a buzzer', 'Show temperature from the DS3231’s sensor']::text[], '{}'::text[], null, '/projects/real-time-clock-display.svg', 'Real-time clock module beside an LCD showing the time and date'),
  ('project-catalogue-2026-10:38', 'Wireless Heart-Rate Data Logger', 'wireless-heart-rate-logger', 'Interdisciplinary', 'advanced', 8, 16, 'Log pulse readings from a heart-rate sensor on an ESP32 and plot them in a browser over Wi-Fi.', '1. Interface
Check the sensor output range is safe for the ESP32’s 3.3 V input.

2. Sample
Read the signal at a steady rate and detect beats.

3. Transmit
Serve BPM and recent samples as JSON.

4. Visualise
Plot BPM over time in the browser and allow CSV download.', array['Sample a biosignal on the ESP32', 'Transmit readings wirelessly', 'Store and visualise time-series data']::text[], array['Sample a biosignal on the ESP32', 'Transmit readings wirelessly', 'Store and visualise time-series data']::text[], array['Arduino IDE with ESP32 board support', 'Basic web development']::text[], array['ESP32, heart rate monitor module', 'Arduino IDE (ESP32 core), browser']::text[], 'A browser shows a live pulse graph and BPM history that can be downloaded.', array['Compare BPM with a manual count', 'Check the data stream for gaps over ten minutes']::text[], array['Education only – not a medical device.', 'Do not connect any sensor powered from mains to the body.']::text[], array['Add a battery and make it wearable', 'Detect and flag noisy segments']::text[], '{}'::text[], 'Verify the heart-rate module’s interface and that its output is safe for the ESP32’s 3.3 V inputs.', '/projects/wireless-heart-rate-logger.svg', 'Heart-rate sensor with an ESP32 sending a pulse graph wirelessly to a laptop'),
  ('project-catalogue-2026-10:39', 'Smart Waste Segregation Prototype', 'smart-waste-segregation', 'Interdisciplinary', 'advanced', 12, 24, 'An experimental sorter that separates wet from dry items using a moisture probe and IR detection, with servo flaps.', '1. Mechanism
Build a chute with a flap that tips items left or right.

2. Detect
IR sensor detects an item arriving; the moisture probe tests whether it is wet.

3. Sort
Servos tip wet items to one bin and dry items to the other.

4. Evaluate
Test a set of sample items and record accuracy.', array['Combine sensors to classify objects', 'Design a sorting mechanism', 'Evaluate accuracy and limitations honestly']::text[], array['Combine sensors to classify objects', 'Design a sorting mechanism', 'Evaluate accuracy and limitations honestly']::text[], array['Basic Arduino programming (setup/loop, digitalRead/Write, Serial Monitor)', 'Basic mechanical design']::text[], array['Arduino Uno, IR sensor, soil-moisture sensor used as a wet/dry probe, 2 SG90 servos', 'Sorting chute and bins (not stocked)', 'Arduino IDE on a laptop']::text[], 'Wet and dry test items are sorted into separate bins most of the time, with documented failure cases.', array['Sort 20 labelled items and compute accuracy', 'Note which materials the sensors cannot tell apart']::text[], array['Use clean, safe test items only – no real waste, glass or sharp objects.', 'Keep water away from the electronics.']::text[], array['Add metal detection with an inductive sensor', 'Try camera-based classification on the Jetson']::text[], array['Sorting chute and two bins']::text[], null, '/projects/smart-waste-segregation.svg', 'Sorting chute with a sensor and servo flaps directing items into wet and dry bins'),
  ('project-catalogue-2026-10:40', 'Indoor Robot Localization', 'indoor-robot-localization', 'Interdisciplinary', 'advanced', 16, 30, 'Estimate the Twin Bot’s position on a known map using a 2D LiDAR and a localization algorithm (e.g. AMCL).', '1. Mount
Fix the LiDAR and mini PC securely on the Twin Bot.

2. Map
Build or load a map of the room.

3. Localise
Run AMCL and drive the robot; watch the particle cloud converge.

4. Evaluate
Compare estimated positions with marked floor positions.', array['Mount and calibrate a LiDAR on a robot', 'Run probabilistic localization', 'Evaluate pose accuracy']::text[], array['Mount and calibrate a LiDAR on a robot', 'Run probabilistic localization', 'Evaluate pose accuracy']::text[], array['Completion of LiDAR mapping (project 19) or ROS experience', 'Probability basics']::text[], array['Twin Bot, 2D LiDAR and mini PC (lab use)', 'ROS, LiDAR driver, map server, AMCL, RViz']::text[], 'The robot’s estimated position on the map stays within a few centimetres of its real position.', array['Drive to five marked points and record position error', 'Kidnap test: move the robot by hand and check recovery']::text[], array['Operate in a clear area at low speed.', 'Never look into the LiDAR emitter.', 'Lab use only.']::text[], array['Add autonomous navigation to goals', 'Fuse wheel odometry and an IMU']::text[], '{}'::text[], 'Confirm the LiDAR driver and a secure mounting on the Twin Bot before publishing as buildable.', '/projects/indoor-robot-localization.svg', 'Robot with a LiDAR on top locating itself on an indoor floor-plan map')
), inserted as (
insert into public.projects (catalogue_key, name, slug, category, difficulty, est_hours_min, est_hours_max, description,
  instructions, learning_outcomes, objectives, prerequisites, hardware_software, expected_outcome, testing_steps,
  safety_notes, extensions, external_requirements, verification_note, image_path, image_alt, status, is_demo)
select v.catalogue_key, v.name,
       case when exists (select 1 from public.projects o where o.slug = v.slug) then v.slug || '-isd' else v.slug end,
       v.category, v.difficulty::public.project_difficulty, v.est_hours_min, v.est_hours_max, v.description, v.instructions,
       v.learning_outcomes, v.objectives, v.prerequisites, v.hardware_software, v.expected_outcome, v.testing_steps,
       v.safety_notes, v.extensions, v.external_requirements, v.verification_note, v.image_path, v.image_alt, 'draft', false
  from v
on conflict (catalogue_key) do nothing
returning id
)
